WITH customer_orders AS (SELECT customer_id, COUNT(*) AS order_count FROM orders WHERE status = 'paid' GROUP BY customer_id)
SELECT ROUND(SUM(CASE WHEN order_count >= 2 THEN 1 ELSE 0 END) * 1.0 / COUNT(*), 3) AS repeat_purchase_rate
FROM customer_orders;
